    [1248805] = { en = "Permanently enchant a Melee Weapon to have a chance to trigger Revelation when a non-periodic spell fails to critically strike. Revelation grants 100% increased critical strike chance to the next spell cast. Revelation's chance to trigger is diminished as your critical strike chance increases.", description = "Incanta permanentemente un'arma da mischia, dando la possibilità di attivare Rivelazione quando un incantesimo non periodico non mette a segno un colpo critico. Rivelazione conferisce al prossimo incantesimo l'100% di probabilità di critico aggiuntiva. La probabilità di attivazione di Rivelazione diminuisce all'aumentare della probabilità di critico." },
