    [1249925] = { en = "$@spelldesc1137 If you spend at least 10 seconds eating you will become well fed and gain $s2 Healing Power for $1249927d. $@spelldesc1243969", description = "$@spelldesc1137 Se mangi per almeno 10 secondi, diventerai ben nutrito e otterrai $s2 potenza curativa per $1249927d. $@spelldesc1243969" },
    [1250887] = { en = "Drink to improve your spatial awareness which allows you to see hidden Mining and Herbalism gathering nodes for $d.\r\n\r\nThis effect persists through death.", description = "Bevi per migliorare la tua percezione spaziale, così da poter vedere i giacimenti di Estrazione mineraria ed Erbalismo nascosti per $d.\r\n\r\nL'effetto persiste anche dopo la morte." },
    [1250889] = { en = "Drink to slightly increase your stealth detection. While you are not moving for $s2 sec, nearby moving stealthed enemies may reveal a heat trail. Lasts for $d.\r\n\r\nThis effect persists through death.", description = "Bevi per aumentare leggermente la tua capacità di individuare i nemici furtivi. Se resti immobile per $s2 sec, i nemici furtivi in movimento nelle vicinanze potrebbero lasciare una scia termica visibile. Dura $d.\r\n\r\nL'effetto persiste anche dopo la morte." },
    [1250900] = { en = "$@spelldesc1250889", description = "$@spelldesc1250889" },
    [1250918] = { en = "Drink to gain $s1 Agility and Intellect for $d. Lasts for $d.", description = "Bevi per ottenere $s1 Agilità e Intelletto per $d. Dura $d." },
    [1250920] = { en = "Drink to gain $s1 maximum health and $s2 armor for $d. Lasts for $d.", description = "Bevi per ottenere $s1 salute massima e $s2 armatura per $d. Dura $d." },
    [1250932] = { en = "Drink to restore $s1 health and $s2 mana every 5 sec. Lasts for $d.", description = "Bevi per rigenerare $s1 salute e $s2 mana ogni 5 sec. Dura $d." },
    [1250940] = { en = "Drink to increase your Intellect by $s1 and chance to critically hit by $s2%. Lasts for $d.", description = "Bevi per aumentare l'Intelletto di $s1 e la probabilità di mettere a segno un colpo critico del $s2%. Dura $d." },
    [1250971] = { en = "Drink to increase spell damage by up to $s1. Lasts for $d.", description = "Bevi per aumentare i danni degli incantesimi fino a $s1. Dura $d." },
    [1250972] = { en = "Drink to increase nature spell damage by up to $s1. Lasts for $d.", description = "Bevi per aumentare i danni degli incantesimi di natura fino a $s1. Dura $d." },
    [1250984] = { en = "Drink to increase your Strength by $s1. Lasts for $d.", description = "Bevi per aumentare la Forza di $s1. Dura $d." },
    [1250985] = { en = "Drink to increase your Strength and Agility by $s1. Lasts for $d.", description = "Bevi per aumentare la Forza e l'Agilità di $s1. Dura $d." },
    [1250986] = { en = "Drink to increase your Strength by $s1 and chance to critically hit by $s2%. Lasts for $d.", description = "Bevi per aumentare la Forza di $s1 e la probabilità di mettere a segno un colpo critico del $s2%. Dura $d." },
    [1251286] = { en = "Handle with care.", description = "Maneggiare con cura." },
    [1251362] = { en = "Reckless handling! Something popped open!", description = "Maneggiato senza cautela! Qualcosa si è aperto!" },
    [1251693] = { en = "Boosts the effect of $@spellname1269962 for $d.", description = "Aumenta l'effetto di $@spellname1269962 per $d." },
    [1251986] = { en = "Gain $U doses of Venomous Blood. Whenever you suffer Bleed damage, one dose is spread to a nearby enemy within $s2 yds. Lasts up to $d.\r\n\r\nVenomous Blood deals $s1 Nature damage per dose when it expires.", description = "Ottieni $U dosi di Sangue velenoso. Ogni volta che subisci danni da Sanguinamento, una dose si diffonde a un nemico vicino entro $s2 m. Dura fino a $d.\r\n\r\nSangue velenoso infligge $s1 danni Natura per dose alla scadenza." },
    [1251993] = { en = "$@spelldesc1251986", description = "$@spelldesc1251986" },
    [1251995] = { en = "$@spelldesc1251986", description = "$@spelldesc1251986" },
    [1252000] = { en = "Bleeding, for testing purposes.", description = "Sanguinamento, a scopo di test." },
    [1252525] = { en = "Throw a fragile concoction at the target area, revealing a cloud of Caustic Smog for $1252526d. Enemies standing within the cloud suffer $1252543s1 Nature damage every $1252543t1 sec.", description = "Lancia una miscela fragile nell'area bersaglio, sprigionando una nube di Fumo caustico per $1252526d. I nemici all'interno della nube subiscono $1252543s1 danni Natura ogni $1252543t1 sec." },
    [1252526] = { en = "$@spelldesc1252525", description = "$@spelldesc1252525" },
    [1252543] = { en = "$@spelldesc1252525", description = "$@spelldesc1252525" },
    [1252544] = { en = "Throw a fragile concoction at the target area, revealing a cloud of Disorienting Smog for $1252545d. Enemies standing within the cloud have their Hit Chance reduced by $1252546s1%. Ineffective against targets above level $1252546s2.", description = "Lancia una miscela fragile nell'area bersaglio, sprigionando una nube di Fumo disorientante per $1252545d. La probabilità di colpire dei nemici all'interno della nube è ridotta di $1252546s1%. Inefficace contro bersagli di livello superiore a $1252546s2." },
    [1252545] = { en = "$@spelldesc1252544", description = "$@spelldesc1252544" },
    [1252546] = { en = "$@spelldesc1252544", description = "$@spelldesc1252544" },
    [1252554] = { en = "Unleash a belch of dragonfire, dealing $s1 Fire damage instantly in a narrow cone in front of you. Affected targets will suffer $s2 additional damage every $t2 sec for $d.", description = "Sprigiona un fiato di fuoco di drago, infliggendo istantaneamente $s1 danni da Fuoco in un cono stretto di fronte a te. I bersagli colpiti subiranno $s2 danni aggiuntivi ogni $t2 sec per $d." },
    [1252558] = { en = "Increases Spell Damage by $s1 against Elementals.  Lasts $d.", description = "Aumenta i danni degli incantesimi di $s1 contro gli Elementali.  Dura $d." },
    [1252559] = { en = "Increases Attack Power by $s1 against Beasts.  Lasts $d.", description = "Aumenta la potenza d'attacco di $s1 contro le Bestie.  Dura $d." },
    [1253348] = { en = "You smell like garbage. Everything around you probably hates the smell.", description = "Puzzi di spazzatura. Probabilmente tutto ciò che ti circonda detesta l'odore." },
    [1253351] = { en = "Taunts all enemies within 30 yards.", description = "Provoca tutti i nemici entro 30 metri." },
    [1254832] = { en = "The Mark of Akir will let the members of The Al'Aketh know that you are friendly.", description = "Il Marchio di Akir farà sapere ai membri di The Al'Aketh che sei amichevole." },
    [1255936] = { en = "Temporarily gives user an enchantment disguising them as their target.", description = "Fornisce temporaneamente all'utilizzatore un incantamento che lo camuffa da bersaglio." },
    [1256717] = { en = "Spin to win, 'till you fly!", description = "Gira e vinci, finché non voli!" },
    [1256867] = { en = "Stealthed.  \r\n", description = "In furtività.  \r\n" },
    [1257010] = { en = "Recently smacked!", description = "Hai appena ricevuto un pugno!" },
    [1257019] = { en = "Looks like you made it angry!", description = "A quanto pare l'hai fatto arrabbiare!" },
    [1257860] = { en = "Attempt to bring down one of the Manticores flying overhead in Shadowgale Forest.", description = "Tenta di abbattere uno dei Manticori che volano sopra la Foresta di Shadowgale." },
    [1258429] = { en = "You are carrying Fillion Flamebreeze. You are encumbered and you may be forced to drop Fillion and flee if you are attacked!\r\n\r\nAvoid combat at all costs.\r\n", description = "Stai trasportando Fillion Flamebreeze. Sei appesantito e potresti essere costretto a lasciare Fillion e fuggire se vieni attaccato!\r\n\r\nEvita il combattimento a ogni costo.\r\n" },
    [1258483] = { en = "Activate the Index Esoteria to gather magical data at the Overlook Standing Stones in the Shen'dar Highlands.", description = "Attiva l'Index Esoteria per raccogliere dati magici presso le Pietre erette dell'Overlook nelle Alture di Shen'dar." },
    [1258494] = { en = "Increases healing done by spells and effects by up to $s1 and damage done by spells and effects by up to $s2.", description = "Aumenta le cure fornite da incantesimi ed effetti fino a $s1 e i danni inflitti da incantesimi ed effetti fino a $s2." },
    [1258784] = { en = "Combine Imbued Tears with Petrified Bark to create a Rudimentary Necromancy Staff.", description = "Combina Lacrime imbevute con Corteccia pietrificata per creare un Bastone rudimentale di negromanzia." },
    [1258812] = { en = "Attempt to infuse necromantic energy into Orgrul's Skeletons.", description = "Tenta di infondere energia negromantica negli scheletri di Orgrul." },
    [1259093] = { en = "Attempt to raise undead by hurling shadowy magic toward suspicious bones.", description = "Tenta di rianimare i non morti lanciando magia d'ombra verso ossa sospette." },
    [1259231] = { en = "Restores $s1 mana and $s2 health. This item cannot be used outside of Skywall.", description = "Ripristina $s1 mana e $s2 salute. Questo oggetto non può essere usato fuori da Skywall." },
    [1259243] = { en = "Suffer $s2% maximum health as Arcane damage and lose $s1% of your maximum mana from walking through unstable mana.", description = "Subisci danni Arcani pari al $s2% della salute massima e perdi il $s1% del mana massimo camminando attraverso mana instabile." },
    [1259246] = { en = "Recovers $s1 maximum mana and allows you to claim the stray mana as an item.", description = "Ripristina $s1 mana massimo e ti permette di reclamare il mana disperso sotto forma di oggetto." },
    [1259630] = { en = "This shriekling is newly born and has poor eyesight. Enemy detection range is greatly reduced.\r\n", description = "Questo strillino è appena nato e ha una vista scarsa. Il raggio di individuazione dei nemici è notevolmente ridotto.\r\n" },
    [1259686] = { en = "Attempt to draw power from a convergence of elements and receive its blessing, increasing your movement and mounted movement speeds by $1259688s1%. Lasts $1259688d if no elemental convergence is nearby, and $1270893d if one is found.\r\n", description = "Tenta di attingere potere da una convergenza di elementi e riceverne la benedizione, aumentando la velocità di movimento e in sella del $1259688s1%. Dura $1259688d se non c'è una convergenza elementale nelle vicinanze e $1270893d se viene trovata.\r\n" },
    [1259705] = { en = "Attempt to tap into the power of a nearby ley line, increasing your Health and Mana regeneration by $1259691s1%. Lasts $1270842d if no ley line is nearby, and $1259691d if one is found.", description = "Tenta di attingere al potere di una linea tellurica vicina, aumentando la rigenerazione di salute e mana del $1259691s1%. Dura $1270842d se non c'è una linea tellurica nelle vicinanze e $1259691d se viene trovata." },
    [1259710] = { en = "Increases your spellcasting, melee, and ranged Haste by $s1%.", description = "Aumenta del $s1% la celerità nel lancio degli incantesimi e negli attacchi in mischia e a distanza." },
    [1259718] = { en = "Instantly removes all Stun effects.", description = "Rimuove istantaneamente tutti gli effetti di stordimento." },
    [1259719] = { en = "Increases your critical strike chance with all spells and attacks by $s1% while you have a mace or two-handed mace equipped.", description = "Aumenta del $s1% la probabilità di critico di tutti gli incantesimi e gli attacchi quando hai equipaggiata una mazza o una mazza a due mani." },
    [1259799] = { en = "Increases your critical strike chance with all spells and attacks by $s1% for $d.", description = "Aumenta del $s1% la probabilità di critico di tutti gli incantesimi e gli attacchi per $d." },
    [1259802] = { en = "Maximum Rage increased by $s1%.", description = "La rabbia massima aumenta del $s1%." },
    [1259803] = { en = "Maximum Energy increased by $s1%.", description = "L'energia massima aumenta del $s1%." },
    [1259812] = { en = "Your next $n damaging abilities have their Energy cost reduced by $s1% and deal $s2% more damage.", description = "Il costo in energia delle tue prossime $n abilità che infliggono danni è ridotto del $s1% e i danni che infliggono aumentano del $s2%." },
    [1259813] = { en = "Your next $n damaging abilities have their Rage cost reduced by $s1% and deal $s2% more damage.", description = "Il costo in rabbia delle tue prossime $n abilità che infliggono danni è ridotto del $s1% e i danni che infliggono aumentano del $s2%." },
    [1259823] = { en = "Your next $n damaging or healing abilities have their Mana cost reduced by $s1% and deal $s2% more damage or healing.", description = "Il costo in mana delle tue prossime $n abilità che infliggono danni o curano è ridotto del $s1% e i danni o le cure che forniscono aumentano del $s2%." },
    [1259904] = { en = "Augment Uthek's Staff with a Draenethyst Crystal.", description = "Potenzia il bastone di Uthek con un cristallo draenethyst." },
    [1259907] = { en = "Your drumbeat inspires allies, increasing the movement speed and mounted movement speed of all party members within $a1 yards by $s1% for $d.", description = "Il ritmo del tuo tamburo ispira gli alleati, aumentando del $s1% la velocità di movimento e quella in sella di tutti i membri del gruppo entro $a1 metri per $d." },
    [1259918] = { en = "Gain $s1% increased movement speed every $s2 sec spent moving, up to a maximum of $s3% increase. Taking damage or standing still will reduce this effect.", description = "La velocità di movimento aumenta del $s1% ogni $s2 sec trascorsi in movimento, fino a un massimo del $s3%. Subire danni o restare fermi riduce questo effetto." },
    [1260031] = { en = "Attempt to dispel the necromantic curse on the Accursed Skull.", description = "Tenta di dissolvere la maledizione negromantica sul Teschio maledetto." },
    [1260270] = { en = "Regenerate $o1% of your maximum Health over $d. Any movement, action, or damage taken will cancel the effect.", description = "Rigenera il $o1% della tua salute massima in $d. Qualsiasi movimento, azione o danno subito annullerà l'effetto." },
    [1260464] = { en = "Burn the stick at the brazier in Outcast Hideaway.", description = "Brucia il bastone al braciere nel Rifugio degli Emarginati." },
    [1260618] = { en = "You light nearby centaur tents on fire.", description = "Dai fuoco alle tende centaure vicine." },
    [1260645] = { en = "Throw the burning stick to attempt to light centaur tents on fire.", description = "Lancia il bastone ardente per tentare di incendiare le tende centaure." },
    [1260743] = { en = "Causes your pet to run away from you.", description = "Fa scappare il tuo famiglio da te." },
    [1261222] = { en = "Launches a sharp glaive towards the enemy.", description = "Lancia una lama affilata contro il nemico." },
    [1261692] = { en = "Resurrect the fallen Khan.", description = "Resuscita il Khan caduto." },
    [1261773] = { en = "Completing this quest awards you with the title \"<Name> of the Magram\" for all characters on your account.\r\n\r\nThis title can only be displayed while you are Exalted or higher with the Magram Clan Centaur.", description = "Completando questa missione, tutti i personaggi del tuo account otterranno il titolo \"<Name> dei Magram\".\r\n\r\nQuesto titolo può essere mostrato solo se hai raggiunto il livello di Esaltato o superiore con i Centauri del Clan Magram." },
    [1261774] = { en = "Completing this quest awards you with the title \"<Name> of the Gelkis\" for this character.\r\n\r\nThis title can only be displayed while you are Exalted or higher with the Gelkis Clan Centaur.", description = "Completando questa missione, questo personaggio otterrà il titolo \"<Name> dei Gelkis\".\r\n\r\nQuesto titolo può essere mostrato solo se hai raggiunto il livello di Esaltato o superiore con i Centauri del Clan Gelkis." },
    [1262321] = { en = "Blessed by Elune, increasing swim speed by $S1%.", description = "Benedetto da Elune, aumenta la velocità di nuoto del $S1%." },
    [1262542] = { en = "Size corrected.", description = "Dimensioni corrette." },
    [1262975] = { en = "Craft a Rock Garden.", description = "Crea un Giardino Roccioso." },
    [1262978] = { en = "Craft Cookie's Feast.", description = "Crea il Banchetto di Cookie." },
    [1262980] = { en = "Craft a Greenhouse.", description = "Crea una Serra." },
    [1262982] = { en = "Craft a Trapper's Workbench.", description = "Crea un Banco da lavoro del Cacciatore." },
    [1262985] = { en = "Craft a Field Guide.", description = "Crea una Guida da campo." },
    [1262990] = { en = "Craft a Fishing Rack.", description = "Crea uno Stendino da pesca." },
    [1262996] = { en = "Craft a Toxin Study.", description = "Crea uno Studio delle tossine." },
    [1262998] = { en = "Craft a Fishing Hut.", description = "Crea una Capanna da pesca." },
    [1263001] = { en = "Craft a Plague Doctor's Laboratory.", description = "Crea il Laboratorio del Medico della Peste." },
    [1263005] = { en = "Craft a Fermenter.", description = "Crea un Fermentatore." },
    [1263031] = { en = "Craft a Tanning Rack.", description = "Crea uno Stendino da concia." },
    [1263032] = { en = "Craft a Spinning Wheel.", description = "Crea un Filatoio." },
    [1263034] = { en = "Craft a Repair Bot.", description = "Crea un Robot riparatore." },
    [1263041] = { en = "Craft an Anvil.", description = "Crea un'Incudine." },
    [1263056] = { en = "Craft an Arcane Salvager.", description = "Crea un Recuperatore arcano." },
    [1263067] = { en = "Craft an Iron Oven.", description = "Crea un Forno di ferro." },
    [1263070] = { en = "Craft a Seed Hybridizer.", description = "Crea un Ibridatore di semi." },
    [1263071] = { en = "Craft a Molten Foundry.", description = "Crea una Fonderia ardente." },
    [1263073] = { en = "Craft a Master Forge.", description = "Crea una Forgia superiore." },
    [1263078] = { en = "Craft an Alchemy Laboratory.", description = "Crea un Laboratorio di alchimia." },
    [1263079] = { en = "Craft a Sewing Machine.", description = "Crea una Macchina da cucire." },
    [1263080] = { en = "Craft a Loom.", description = "Crea un Telaio." },
    [1263082] = { en = "Craft an Arcane Forge.", description = "Crea una Forgia arcana." },
    [1263083] = { en = "Craft an Anarchist's Workbench.", description = "Crea un Banco da lavoro dell'anarchico." },
    [1263086] = { en = "Inflicts $s2 physical damage to all players within $2r yards and reduces their healing recieved by $S1% for $d1.", description = "Infligge $s2 danni fisici a tutti i giocatori entro $2r metri e riduce le loro cure ricevute del $S1% per $d1." },
    [1263129] = { en = "Deals $S1 physical damage to the current target, causing them to bleed for $S2 damage every $T2 sec for $d.", description = "Infligge $S1 danni fisici al bersaglio attuale, facendolo sanguinare e infliggendogli $S2 danni ogni $T2 sec per $d." },
    [1263244] = { en = "$@spelldesc1263733\r\n", description = "$@spelldesc1263733\r\n" },
    [1263260] = { en = "Deal $s1 Physical damage and embeds thorns in the target which cause melee attacks received to deal an additional $s2 Physical damage.", description = "Infligge $s1 danni fisici e conficca spine nel bersaglio, che fanno sì che gli attacchi in mischia ricevuti infliggano $s2 danni fisici aggiuntivi." },
    [1263261] = { en = "$@spelldesc1263260", description = "$@spelldesc1263260" },
    [1263284] = { en = "Increases your size and damage done whenever you successfully cast Mana Burn.\r\n\r\nAt $U stacks, you will detonate.", description = "Aumenta la tua dimensione e i danni inflitti ogni volta che lanci con successo Bruciatura del Mana.\r\n\r\nA $U accumuli, esploderai." },
    [1263333] = { en = "You are overflowing with mana and will explode, dealing $s1% of nearby enemies maximum health as Arcane damage and knock them away.\r\n\r\nYou will die in the process.", description = "Sei stracolmo di mana ed esploderai, infliggendo danni arcani pari al $s1% della salute massima ai nemici vicini e respingendoli.\r\n\r\nMorirai durante il processo." },
    [1263343] = { en = "Attempt to summon an Undead Ravager to fight by your side.", description = "Tenta di evocare un Devastatore Non Morto che combatta al tuo fianco." },
    [1263726] = { en = "$@spelldesc1263733", description = "$@spelldesc1263733" },
    [1263733] = { en = "Spits a bolt of acid that inflicts $S1 nature damage to all players within $r of where the acid lands. ", description = "Sputa un dardo d'acido che infligge $S1 danni naturali a tutti i giocatori entro $r dal punto in cui l'acido atterra. " },
    [1263738] = { en = "Gharalis' acid burns, inflicting $s1 nature damage every $t1 sec.", description = "L'acido di Gharalis brucia, infliggendo $s1 danni naturali ogni $t1 sec." },
    [1263770] = { en = "Attempt to dispel the necromantic curse on buried undead.", description = "Tenta di dissolvere la maledizione necromantica sui non morti sepolti." },
    [1264548] = { en = "Pounce on the target, dealing $s1 Physical damage and stunning them for $d.", description = "Si avventa sul bersaglio, infliggendo $s1 danni fisici e stordendolo per $d." },
    [1264600] = { en = "Unleashing fel magic on death, dealing $S1 shadow damage to all enemies within $r yards.", description = "Scatena la magia vile alla morte, infliggendo $S1 danni d'ombra a tutti i nemici entro $r metri." },
    [1264639] = { en = "Mine a Ghostly Iron Deposit.", description = "Estrai un Deposito di Ferro spettrale." },
    [1264747] = { en = "Stings the target, inflicting $s1 Nature damage every $t1 sec for $d.", description = "Punzecchia il bersaglio, infliggendo $s1 danni naturali ogni $t1 sec per $d." },
    [1265634] = { en = "Deals $s1 Arcane damage. Deals $s2 times as much damage to Naga and Satyrs.", description = "Infligge $s1 danni arcani. Infligge danni pari a $s2 volte tanto a Naga e Satiri." },
    [1265776] = { en = "Summon a torrential downpour of enchanted water to extinguish Woodwyrd.", description = "Evoca un torrenziale acquazzone di acqua incantata per spegnere Woodwyrd." },
    [1265886] = { en = "Assemble $s2 Vibrant Flowers to create a Benevolent Bouquet.", description = "Assembla $s2 Fiori Vivaci per creare un Bouquet Benevolo." },
    [1266240] = { en = "Spit corrosive acid at an enemy, reducing its armor by $s1 per stack. Can be applied up to $U times. Lasts $d.", description = "Sputa acido corrosivo contro un nemico, riducendone l'armatura di $s1 per accumulo. Può essere applicato fino a $U volte. Dura $d." },
    [1266339] = { en = "Add a missing page to Evenshade's journal.", description = "Aggiunge una pagina mancante al diario di Evenshade." },
    [1267113] = { en = "Reduces damage by $S1%.", description = "Riduce i danni del $S1%." },
    [1267193] = { en = "You are not yet permitted into the city of Dalaran.", description = "Non ti è ancora consentito entrare nella città di Dalaran." },
    [1267199] = { en = "Halt! A Kirin Tor guard has marked you for transference.", description = "Fermo! Una guardia del Kirin Tor ti ha segnalato per il trasferimento." },
    [1268774] = { en = "Transforms into a Dread Raven, granting access to new abilities.", description = "Si trasforma in un Dread Raven, ottenendo accesso a nuove abilità." },
    [1268815] = { en = "Assumes the form of a vicious spider Wild God, gaining its abilities for $d.", description = "Assume la forma di un feroce Wild God ragno, ottenendone le abilità per $d." },
    [1268826] = { en = "Assumes the form of a mighty thunder lizard for $d.", description = "Assume la forma di una possente lucertola del tuono per $d." },
    [1269045] = { en = "Throws the Emerald Dream into turmoil, inflicting $1269185s1 nature damage to all players every $t1 sec.", description = "Getta l'Emerald Dream nel caos, infliggendo $1269185s1 danni da natura a tutti i giocatori ogni $t1 sec." },
    [1269047] = { en = "Summons a Wild Spirit every $T1 sec.These spirits will close in on the Wild King's enemies and detonate.", description = "Evoca uno Wild Spirit ogni $T1 sec.Questi spiriti si avvicineranno ai nemici del Wild King e detonerenno." },
    [1269048] = { en = "$@spelldesc<1269532>\r\n", description = "$@spelldesc<1269532>\r\n" },
    [1269140] = { en = "Tinker with your prototype gadget, hoping for a positive result.", description = "Smanetta con il tuo gadget prototipo, sperando in un risultato positivo." },
    [1269150] = { en = "Overwhelmed by his own powers, the Wild King has assumed a horrific new form, granting access to the abilities of several Wild Gods.", description = "Sopraffatto dai suoi stessi poteri, il Wild King ha assunto una nuova forma orribile, ottenendo accesso alle abilità di diversi Wild Gods." },
    [1269185] = { en = "$@spelldesc<1269045>", description = "$@spelldesc<1269045>" },
    [1269216] = { en = "Inflicts $s1 Fire damage and stuns targets in a 3 yard radius for $d.  Any damage will break the effect.", description = "Infligge $s1 danni da Fuoco e stordisce i bersagli entro un raggio di 3 yard per $d. Qualsiasi danno interrompe l'effetto." },
    [1269330] = { en = "Inflicts $s1 Fire damage and stuns targets for $d in a 3 yard radius.  Any damage will break the effect.", description = "Infligge $s1 danni da Fuoco e stordisce i bersagli entro un raggio di 3 yard per $d. Qualsiasi danno interrompe l'effetto." },
    [1269334] = { en = "Inflicts $s1 Fire damage and stuns targets in a $a1 yard radius for $d.  Any damage will break the effect.", description = "Infligge $s1 danni da Fuoco e stordisce i bersagli entro un raggio di $a1 yard per $d. Qualsiasi danno interrompe l'effetto." },
    [1269337] = { en = "Burns $s1 mana from those in the blast radius and does 50% of the mana drained in damage to the target.  Also Silences targets in the blast for $d.", description = "Brucia $s1 mana di chi si trova nel raggio dell'esplosione e infligge al bersaglio danni pari al 50% del mana prosciugato. Inoltre silenzia per $d i bersagli coinvolti nell'esplosione." },
    [1269339] = { en = "Rips the dimensional walls asunder and transports you to Kaylaena's Workshop on Mount Hyjal. Technical problems have a high chance to occur with this mad combination of goblin and gnomish engineering.", description = "Squarcia le pareti dimensionali e ti trasporta al laboratorio di Kaylaena sul Mount Hyjal. È molto probabile che si verifichino problemi tecnici con questa folle combinazione di ingegneria goblin e gnomesca." },
    [1269404] = { en = "Directs a bolt of negative energy at the enemy inflicting $s1 Shadow damage and increasing the amount of damage taken by $@spellname1269404 by $s2% per stack for $d.", description = "Scaglia un dardo di energia negativa contro il nemico, infliggendo $s1 danni da ombra e aumentando del $s2% per accumulo i danni subiti da $@spellname1269404 per $d." },
    [1269508] = { en = "Inflicts $s1% nature damage to all players within $r1 yards.", description = "Infligge $s1% danni da natura a tutti i giocatori entro $r1 yard." },
    [1269510] = { en = "$@spelldesc<1269047>", description = "$@spelldesc<1269047>" },
    [1269525] = { en = "$@spelldesc<1269532>\r\n", description = "$@spelldesc<1269532>\r\n" },
    [1269526] = { en = "$@spelldesc<1269532>", description = "$@spelldesc<1269532>" },
    [1269532] = { en = "Creates a pool of powerful absorbing magics. Players within this magic suffer $S1 nature damage, transferring that much health to the Wild King every $T1 sec.", description = "Crea una pozza di potenti magie assorbenti. I giocatori al suo interno subiscono $S1 danni da natura, trasferendo altrettanta salute al Wild King ogni $T1 sec." },
    [1269546] = { en = "Deals $s1 Shadow damage to enemies within $a1 yards, interrupting any spells being cast for $d.", description = "Infligge $s1 danni da ombra ai nemici entro $a1 yard, interrompendo per $d gli incantesimi in corso." },
    [1269554] = { en = "Haunts nearby enemies, inflicting Shadow damage.", description = "Infesta i nemici vicini, infliggendo danni da ombra." },
    [1269557] = { en = "Inflicts 15% of nearby targets health as Shadow damage.", description = "Infligge danni da ombra pari al 15% della salute dei bersagli vicini." },
    [1269558] = { en = "$@spelldesc<1269532>\r\n", description = "$@spelldesc<1269532>\r\n" },
    [1269577] = { en = "Gain the ability to purchase Forgery Quills from an uncertified scribe, which allow you to reroll any Craftsman's Writ into a new one of Apprentice skill.", description = "Ottieni la possibilità di acquistare Piume contraffatte da un amanuense non certificato, che ti consentono di ritirare qualsiasi Mandato dell'artigiano e ottenerne uno nuovo di livello Apprendista." },
    [1269580] = { en = "Gain the ability to purchase Forgery Quills from an uncertified scribe, which allow you to reroll any Craftsman's Writ into a new one of Journeyman skill.", description = "Ottieni la possibilità di acquistare Piume contraffatte da un amanuense non certificato, che ti consentono di ritirare qualsiasi Mandato dell'artigiano e ottenerne uno nuovo di livello Praticante." },
    [1269581] = { en = "Gain the ability to purchase Forgery Quills from an uncertified scribe, which allow you to reroll any Craftsman's Writ into a new one of Expert skill.", description = "Ottieni la possibilità di acquistare Piume contraffatte da un amanuense non certificato, che ti consentono di ritirare qualsiasi Mandato dell'artigiano e ottenerne uno nuovo di livello Esperto." },
    [1269582] = { en = "Gain the ability to purchase Forgery Quills from an uncertified scribe, which allow you to reroll any Craftsman's Writ into a new one of Artisan skill.", description = "Ottieni la possibilità di acquistare Piume contraffatte da un amanuense non certificato, che ti consentono di ritirare qualsiasi Mandato dell'artigiano e ottenerne uno nuovo di livello Artigiano." },
    [1269585] = { en = "The Wild King releases a dreadful screech, causing all players within $r1 yards to run in fear for $t1 sec.", description = "Il Wild King lancia un terrificante stridio, facendo fuggire terrorizzati tutti i giocatori entro $r1 yard per $t1 sec." },
    [1269600] = { en = "Slap a forged delivery receipt onto an empty Waylaid Crate, allowing you to return it to the $?pc923[Durotar Supply and Logistics][Azeroth Commerce Authority] for +$s2 reputation.", description = "Applica una ricevuta di consegna contraffatta a una Cassa di rifornimenti abbandonata vuota, consentendoti di restituirla al $?pc923[Durotar Supply and Logistics][Azeroth Commerce Authority] per ottenere +$s2 reputazione." },
    [1269670] = { en = "Tear open the envelope to reveal the writ. The resulting order will be for an Apprentice craftsman.", description = "Apri la busta per rivelare il mandato. L'ordine risultante sarà per un artigiano Apprendista." },
    [1269671] = { en = "Tear open the envelope to reveal the writ. The resulting order will be for a Journeyman craftsman.", description = "Apri la busta per rivelare il mandato. L'ordine risultante sarà per un artigiano Praticante." },
    [1269673] = { en = "Tear open the envelope to reveal the writ. The resulting order will be for an Expert craftsman.", description = "Apri la busta per rivelare il mandato. L'ordine risultante sarà per un artigiano Esperto." },
    [1269675] = { en = "Tear open the envelope to reveal the writ. The resulting order will be for an Artisan craftsman.", description = "Apri la busta per rivelare il mandato. L'ordine risultante sarà per un artigiano Artigiano." },
    [1269692] = { en = "Fill with water from the snowmelt pond in front of Deadwood Den.", description = "Riempi con l'acqua dello stagno alimentato dallo scioglimento della neve davanti a Deadwood Den." },
    [1269868] = { en = "Charges to a target, deals $s1 physical damage to all targets within 15 yards, stunning them for $d.\r\n", description = "Carica contro un bersaglio, infliggendo $s1 danni fisici a tutti i bersagli entro 15 yard e stordendoli per $d.\r\n" },
    [1269872] = { en = "Haunts nearby enemies, inflicting $s1 Shadow damage every $t1 sec.", description = "Infesta i nemici vicini, infliggendo $s1 danni da ombra ogni $t1 sec." },
    [1269877] = { en = "Deals $s1 physical damage to all targets within 15 yards, stunning them for $d.", description = "Infligge $s1 danni fisici a tutti i bersagli entro 15 yard e li stordisce per $d." },
    [1269934] = { en = "Instantly activates the effects of Convoke the Spirits, Assimilation and Dreamfall for the remainder of the encounter.", description = "Attiva istantaneamente gli effetti di Convoke the Spirits, Assimilation e Dreamfall per il resto dell'incontro." },
    [1269962] = { en = "Increases damage and healing done by magical spells and effects by $s1% for the duration of the intense sunlight.", description = "Aumenta del $s1% i danni inflitti e le cure fornite da incantesimi ed effetti magici per tutta la durata della luce solare intensa." },
    [1270173] = { en = "Carrying the Alliance battle standard.", description = "Porti lo stendardo da battaglia dell'Alleanza." },
    [1270187] = { en = "Invigorated by fragmented souls. For each stack of $@spellname1270187 you gain a $s1% increase to Shadow damage.", description = "Rinforzato da anime frammentate. Per ogni accumulo di $@spellname1270187, i danni da ombra aumentano del $s1%." },
    [1270257] = { en = "Inflicts $1270260s1 nature damage to all players every $T1 sec.", description = "Infligge $1270260s1 danni da natura a tutti i giocatori ogni $T1 sec." },
    [1270260] = { en = "$@spelldesc1270257", description = "$@spelldesc1270257" },
    [1270422] = { en = "Allows the caster to levitate, floating a few feet above the ground.  While levitating, you will fall at a reduced speed and travel over water-like surfaces.  ", description = "Permette a chi lo lancia di levitare, fluttuando a pochi piedi dal suolo. Mentre leviti, cadi più lentamente e puoi spostarti su superfici simili all'acqua.  " },
    [1270427] = { en = "Inflicts $s1 Shadow damage every $t1 sec to enemies within $a1 yds.", description = "Infligge $s1 danni da ombra ogni $t1 sec. ai nemici entro $a1 yds." },
    [1270470] = { en = "Reduces the mana cost of shapeshifting spells by $s1.", description = "Riduce il costo in mana degli incantesimi di mutamento di forma di $s1." },
    [1270478] = { en = "Reduces the mana cost of Lightning Bolt by $s1 mana.", description = "Riduce di $s1 mana il costo di Dardo Fulminante." },
    [1270490] = { en = "Increases your Armor contribution from items by $s1%.", description = "Aumenta il contributo all'armatura fornito dagli oggetti del $s1%." },
    [1270492] = { en = "Reduces the mana cost of your totems by $s1%.", description = "Riduce il costo in mana dei tuoi totem del $s1%." },
    [1270498] = { en = "Attempts to sunder the soul of a nearby enemy.", description = "Tenta di lacerare l'anima di un nemico vicino." },
    [1270643] = { en = "The power of the Emerald Dream seeps out of Nythus, reducing his mana regeneration by 100% for $d.", description = "Il potere del Sogno di Smeraldo trasuda da Nythus, riducendo la sua rigenerazione del mana del 100% per $d." },
    [1270648] = { en = "Nythus has awakened from the dream, and is unable to maintain his connection to the waking world. Stunned, and all incoming damage is increased by $S2%.", description = "Nythus si è risvegliato dal sogno e non riesce a mantenere il legame con il mondo della veglia. Stordito, subisce il $S2% di danni in più da tutti gli attacchi." },
    [1270810] = { en = "The power of the Emerald Dream seeps out of Nythus, increasing mana regeneration for all players by $S1% but increasing all the damage they take and receive by $S2%.\r\n\r\nHaste is also increased by $S4%.", description = "Il potere del Sogno di Smeraldo trasuda da Nythus, aumentando la rigenerazione del mana di tutti i giocatori del $S1% ma aumentando del $S2% tutti i danni che infliggono e subiscono.\r\n\r\nLa celerità aumenta inoltre del $S4%." },
    [1270825] = { en = "Inflicts %S1 physical damage to the current target, applying an aura that reduces armor by $s2%.", description = "Infligge %S1 danni fisici al bersaglio attuale e applica un'aura che riduce l'armatura del $s2%." },
    [1270940] = { en = "Restores $s1 charges to a SAF-T or EZ-Thro brand device in your possession that does not involve explosions. It would be completely Unsafe with explosives.", description = "Ripristina $s1 cariche a un dispositivo di marca SAF-T o EZ-Thro in tuo possesso che non comporta esplosioni. Con gli esplosivi sarebbe del tutto Unsafe." },
    [1270941] = { en = "Turns the target into a chicken for $1270942d. Well, that is assuming the transmogrification polarity has not been reversed...", description = "Trasforma il bersaglio in una gallina per $1270942d. Beh, sempre che la polarità della trasmogrificazione non sia stata invertita..." },
    [1271044] = { en = "TRANSPORTER FAILURE!!! SPATIAL LOCK NOT ACHIEVED!! LOCATION UNDETERMINED!", description = "ERRORE DI TELETRASPORTO!!! BLOCCO SPAZIALE NON RAGGIUNTO!! POSIZIONE INDETERMINATA!" },
    [1271047] = { en = "$s1 Shadow damage inflicted to players within $a1 yards.", description = "Infligge $s1 danni da ombra ai giocatori entro $a1 metri." },
    [1271049] = { en = "Glide downward through the air for $1271020d while controlling your direction of travel.", description = "Planate nell'aria per $1271020d controllando la direzione del movimento." },
    [1271091] = { en = "Inflicts $S1 nature damage to all players.", description = "Infligge $S1 danni da natura a tutti i giocatori." },
    [1271100] = { en = "$s1 Arcane damage inflicted to players within $a1 yards.", description = "Infligge $s1 danni arcani ai giocatori entro $a1 metri." },
    [1271103] = { en = "Begins taming a Vuldren Alpha to be your companion for 10 minutes.  If you lose the beast's attention for any reason, the taming process will fail.", description = "Inizia ad addomesticare un Alfa Vuldren perché diventi il tuo compagno per 10 minuti. Se perdi per qualsiasi motivo l'attenzione della bestia, il processo di addomesticamento fallirà." },
    [1271266] = { en = "Cloaks the user in a stealth field for up to $d. Cannot be used in combat. The field lasts for up to ${$m4/1000} sec after moving.", description = "Avvolge l'utilizzatore in un campo di furtività per un massimo di $d. Non può essere usato in combattimento. Il campo dura fino a ${$m4/1000} sec dopo essersi mossi." },
    [1271338] = { en = "$@spelldesc1270940", description = "$@spelldesc1270940" },
    [1271344] = { en = "$@spelldesc1270940", description = "$@spelldesc1270940" },
    [1271346] = { en = "$@spelldesc1270940", description = "$@spelldesc1270940" },
    [1271347] = { en = "$@spelldesc1270940", description = "$@spelldesc1270940" },
    [1271348] = { en = "$@spelldesc1270940", description = "$@spelldesc1270940" },
    [1271349] = { en = "$@spelldesc1270940", description = "$@spelldesc1270940" },
    [1271350] = { en = "$@spelldesc1270940", description = "$@spelldesc1270940" },
    [1271351] = { en = "Anara Chillwind channels the grace of Elune infusing random enemies with the might of a star inflicting $s1 Arcane damage every $t1 sec for $d. Upon removal, a collapsing star is formed. Enemies within the star suffer $1271414s2 Arcane damage every $1271414t2 sec and have their movement speed reduced by $1271414s1%.", description = "Anara Chillwind incanala la grazia di Elune, infondendo a nemici casuali la potenza di una stella, che infligge $s1 danni arcani ogni $t1 sec per $d. Alla rimozione, si forma una stella collassante. I nemici all'interno della stella subiscono $1271414s2 danni arcani ogni $1271414t2 sec e la loro velocità di movimento è ridotta del $1271414s1%." },
    [1271352] = { en = "Anara Chillwind channels the rage of Elune infusing random enemies with the weight of a singularity inflicting $s1 Shadow damage every $t1 sec for $d. Upon removal, a black hole is formed. Enemies within the void suffer $1271414s2 Shadow damage every $1271414t2 sec and are slowly pulled toward the center. ", description = "Anara Chillwind incanala la furia di Elune, infondendo a nemici casuali il peso di una singolarità, che infligge $s1 danni da ombra ogni $t1 sec per $d. Alla rimozione, si forma un buco nero. I nemici all'interno del vuoto subiscono $1271414s2 danni da ombra ogni $1271414t2 sec e vengono lentamente attirati verso il centro. " },
    [1271357] = { en = "$@spelldesc1271351", description = "$@spelldesc1271351" },
    [1271414] = { en = "$@spelldesc1271351", description = "$@spelldesc1271351" },
    [1271421] = { en = "Rewrite an undesired Craftsman's Writ, resulting in a random writ from the same tier.", description = "Riscrive una Commissione dell'Artigiano indesiderata, ottenendo una commissione casuale dello stesso grado." },
    [1271422] = { en = "Rewrite the contents of an undesired Craftsman's Writ, resulting in another writ of Journeyman skill.", description = "Riscrive il contenuto di una Commissione dell'Artigiano indesiderata, ottenendo un'altra commissione di abilità da Apprendista." },
    [1271423] = { en = "Rewrite the contents of an undesired Craftsman's Writ, resulting in another writ of Expert skill.", description = "Riscrive il contenuto di una Commissione dell'Artigiano indesiderata, ottenendo un'altra commissione di abilità da Esperto." },
    [1271424] = { en = "Rewrite the contents of an undesired Craftsman's Writ, resulting in another writ of Artisan skill.", description = "Riscrive il contenuto di una Commissione dell'Artigiano indesiderata, ottenendo un'altra commissione di abilità da Artigiano." },
    [1271844] = { en = "Inflicts $S1 physical damage to the current target and increases their damage physical damage taken by $S2% for $d.", description = "Infligge $S1 danni fisici al bersaglio attuale e aumenta del $S2% i danni fisici subiti dal bersaglio per $d." },
    [1271848] = { en = "Inflicts $S1 physical damage to all players within $r1 yards.", description = "Infligge $S1 danni fisici a tutti i giocatori entro $r1 metri." },
    [1271865] = { en = "$@spelldesc<1289927>", description = "$@spelldesc<1289927>" },
    [1271866] = { en = "$@spelldesc<1271867>", description = "$@spelldesc<1271867>" },
    [1271867] = { en = "Conjures the power of mist, dealing $S1 nature damage every $1271866t1 sec.", description = "Evoca il potere della nebbia, infliggendo $S1 danni da natura ogni $1271866t1 sec." },
    [1271868] = { en = "$@spelldesc<1271867>", description = "$@spelldesc<1271867>" },
    [1272073] = { en = "How to pull ore and stone from mineral veins for use in Engineering and Blacksmithing. Requires a Mining Pick.", description = "Come estrarre minerale e pietra dai filoni per usarli in Ingegneria e Forgiatura. Richiede un piccone da minatore." },
    [1272222] = { en = "Collecting herbs.\r\n", description = "Raccolta di erbe.\r\n" },
    [1272591] = { en = "$@spelldesc<1272606>", description = "$@spelldesc<1272606>" },
    [1272606] = { en = "Causes arrows to rain from the sky at the location of a random target, inflicting $S1% damage every $T1 sec.", description = "Fa piovere frecce dal cielo sul luogo di un bersaglio casuale, infliggendo il $S1% di danni ogni $T1 sec." },
    [1272758] = { en = "Strikes an enemy with an arrow that bounces to another nearby enemy. The spell affects up to $x1 targets, causing $s1 physical damage to each.", description = "Colpisce un nemico con una freccia che rimbalza su un altro nemico vicino. L'incantesimo colpisce fino a $x1 bersagli, infliggendo $s1 danni fisici a ciascuno." },
    [1272771] = { en = "Deals $S1 physical damage to the current enemy target.", description = "Infligge $S1 danni fisici al bersaglio nemico attuale." },
    [1272794] = { en = "Elune blesses Sylvestris, reducing all incoming damage by $S1%.", description = "Elune benedice Sylvestris, riducendo del $S1% tutti i danni subiti." },
    [1272804] = { en = "Elune blesses Stormwraith, reducing all incoming damage by $S1%.\r\n", description = "Elune benedice Stormwraith, riducendo del $S1% tutti i danni subiti.\r\n" },
    [1272959] = { en = "$@spelldesc1272962", description = "$@spelldesc1272962" },
    [1272962] = { en = " Leaps to a target, dealing $s1 nature damage and slowing the target and all units within $a1 yards by $S2% for $d.", description = " Balza su un bersaglio, infliggendo $s1 danni da natura e rallentando il bersaglio e tutte le unità entro $a1 metri del $S2% per $d." },
    [1272973] = { en = "Applies a powerful curse to the target, dealing $s1 shadow damage after $d.", description = "Applica una potente maledizione al bersaglio, infliggendo $s1 danni da ombra dopo $d." },
    [1272982] = { en = "Ruptures the target, causing them to bleed for $s1% damage every $T2 sec for $d.", description = "Squarcia il bersaglio, facendolo sanguinare e infliggendogli il $s1% di danni ogni $T2 sec per $d." },
    [1273312] = { en = "Provide sustenance to a Rog'mar Trainee.", description = "Fornisci sostentamento a un apprendista Rog'mar." },
    [1273320] = { en = "Hunger subsides.", description = "La fame si placa." },
    [1276954] = { en = "This container needs to be filled with water from the brackish lake near the southern Wetlands waterfall.", description = "Questo contenitore va riempito con l'acqua del lago salmastro vicino alla cascata meridionale delle Paludi." },
    [1277050] = { en = "This container needs to be filled with water from Stonewatch Falls in Redridge Mountains.", description = "Questo contenitore va riempito con l'acqua delle Cascate di Stonewatch nei Monti Redridge." },
    [1277112] = { en = "This container should be filled from the body of water around Astranaar.", description = "Questo contenitore va riempito con l'acqua intorno ad Astranaar." },
    [1277336] = { en = "Summons and dismisses a rideable Purple Skeletal Horse. This is a very fast mount.", description = "Evoca e congeda un Cavallo scheletrico viola cavalcabile. Questa cavalcatura è molto veloce." },
    [1277364] = { en = "Channeling dark and unknowable magic, granting Bonesnout the Unbroken 1 stack of Profane Bulwark.", description = "Canalizza una magia oscura e inconoscibile, conferendo a Bonesnout l'Infranto 1 accumulo di Baluardo profano." },
    [1277406] = { en = "The Satyr's rituals empower Bonesnout, reducing incoming damage by $S1% per stack.\r\n", description = "I rituali dei satiri potenziano Bonesnout, riducendo i danni subiti del $S1% per accumulo.\r\n" },
    [1277417] = { en = "$@spelldesc1277364", description = "$@spelldesc1277364" },
    [1277431] = { en = "$@spelldesc1277364", description = "$@spelldesc1277364" },
    [1277455] = { en = "Confuses up to $i enemies within $a1 yds for $d. Any damage taken will break the effect.", description = "Confusiona fino a $i nemici entro $a1 m per $d. Qualsiasi danno subito interromperà l'effetto." },
    [1277462] = { en = "Place a Holy ward on an ally for $d. The next time this ally takes damage dropping their Health below $s1%, they will gain a shield absorbing $1277463s2 damage and begin healing for $1277456o2 Health over $1277456d. A target may be affected by only one Contingency Plan.", description = "Pone una protezione sacra su un alleato per $d. La prossima volta che questo alleato subisce danni che portano la sua Salute sotto il $s1%, otterrà uno scudo che assorbe $1277463s2 danni e inizierà a recuperare $1277456o2 Salute in $1277456d. Un bersaglio può essere influenzato da un solo Piano di contingenza." },
    [1277634] = { en = "Place a Holy ward on an ally for $d. The next time this ally takes damage dropping their Health below $s1%, they will gain a shield absorbing $1277464s2 damage and begin healing for $1277457o2 Health over $1277457d. A target may be affected by only one Contingency Plan.", description = "Pone una protezione sacra su un alleato per $d. La prossima volta che questo alleato subisce danni che portano la sua Salute sotto il $s1%, otterrà uno scudo che assorbe $1277464s2 danni e inizierà a recuperare $1277457o2 Salute in $1277457d. Un bersaglio può essere influenzato da un solo Piano di contingenza." },
    [1277638] = { en = "Place a Holy ward on an ally for $d. The next time this ally takes damage dropping their Health below $s1%, they will gain a shield absorbing $1277465s2 damage and begin healing for $1277458o2 Health over $1277458d. A target may be affected by only one Contingency Plan.", description = "Pone una protezione sacra su un alleato per $d. La prossima volta che questo alleato subisce danni che portano la sua Salute sotto il $s1%, otterrà uno scudo che assorbe $1277465s2 danni e inizierà a recuperare $1277458o2 Salute in $1277458d. Un bersaglio può essere influenzato da un solo Piano di contingenza." },
    [1277639] = { en = "Place a Holy ward on an ally for $d. The next time this ally takes damage dropping their Health below $s1%, they will gain a shield absorbing $1277467s2 damage and begin healing for $1277459o2 Health over $1277459d. A target may be affected by only one Contingency Plan.", description = "Pone una protezione sacra su un alleato per $d. La prossima volta che questo alleato subisce danni che portano la sua Salute sotto il $s1%, otterrà uno scudo che assorbe $1277467s2 danni e inizierà a recuperare $1277459o2 Salute in $1277459d. Un bersaglio può essere influenzato da un solo Piano di contingenza." },
    [1277640] = { en = "Place a Holy ward on an ally for $d. The next time this ally takes damage dropping their Health below $s1%, they will gain a shield absorbing $1277466s2 damage and begin healing for $1277460o2 Health over $1277460d. A target may be affected by only one Contingency Plan.", description = "Pone una protezione sacra su un alleato per $d. La prossima volta che questo alleato subisce danni che portano la sua Salute sotto il $s1%, otterrà uno scudo che assorbe $1277466s2 danni e inizierà a recuperare $1277460o2 Salute in $1277460d. Un bersaglio può essere influenzato da un solo Piano di contingenza." },
    [1277794] = { en = "Begins taming a Rockhide Boar to be your companion for 10 minutes.  If you lose the beast's attention for any reason, the taming process will fail.", description = "Inizia a domare un cinghiale Rocciadura perché diventi il tuo compagno per 10 minuti. Se per qualsiasi motivo perdi l'attenzione della bestia, il processo di addomesticamento fallirà." },
    [1277808] = { en = "Plant a seedling.", description = "Pianta un germoglio." },
    [1278028] = { en = "Begins taming a Gray Forest Wolf to be your companion for 10 minutes.  If you lose the beast's attention for any reason, the taming process will fail.", description = "Inizia a domare un lupo delle foreste grigie perché diventi il tuo compagno per 10 minuti. Se per qualsiasi motivo perdi l'attenzione della bestia, il processo di addomesticamento fallirà." },
    [1278029] = { en = "Begins taming a Young Forest Bear to be your companion for 10 minutes.  If you lose the beast's attention for any reason, the taming process will fail.", description = "Inizia a domare un giovane orso delle foreste perché diventi il tuo compagno per 10 minuti. Se per qualsiasi motivo perdi l'attenzione della bestia, il processo di addomesticamento fallirà." },
    [1278062] = { en = "Allows the herbalist to add features to a wilderness camp.", description = "Permette all'erbalista di aggiungere migliorie a un accampamento selvaggio." },
    [1278067] = { en = "Allows the fisher to add features to a wilderness camp.", description = "Permette al pescatore di aggiungere migliorie a un accampamento selvaggio." },
    [1278068] = { en = "Allows the skinner to add features to a wilderness camp.", description = "Permette al conciatore di aggiungere migliorie a un accampamento selvaggio." },
    [1278910] = { en = "Deal $s1% of your maximum health every $t1 sec.\r\n\r\nFor testing purposes only, of course.", description = "Subisci $s1% della tua salute massima ogni $t1 sec.\r\n\r\nSolo a scopo di test, naturalmente." },
    [1278974] = { en = "Right-click to fill Tharian's Vial at a source of Untainted Water on Mount Hyjal.", description = "Clic destro per riempire l'ampolla di Tharian presso una fonte di Acqua incontaminata sul Monte Hyjal." },
    [1279600] = { en = "Remove fel taint and stolen energies from the target.", description = "Rimuove la corruzione vile e le energie sottratte dal bersaglio." },
    [1280003] = { en = "Begins taming a Windsong Crawler to be your companion for 10 minutes.  If you lose the beast's attention for any reason, the taming process will fail.", description = "Inizia a domare un crawler di Canto del Vento perché diventi il tuo compagno per 10 minuti. Se per qualsiasi motivo perdi l'attenzione della bestia, il processo di addomesticamento fallirà." },
    [1280046] = { en = "Begins taming an Ornery Galestrider to be your companion for 10 minutes. If you lose the beast's attention for any reason, the taming process will fail.", description = "Inizia a domare un cavalcavento irascibile perché diventi il tuo compagno per 10 minuti. Se per qualsiasi motivo perdi l'attenzione della bestia, il processo di addomesticamento fallirà." },
    [1280353] = { en = "Taking increased damage from Consecration.", description = "Subisce danni aumentati da Consacrazione." },
    [1280472] = { en = "Deals $s1 Arcane damage to the current target.", description = "Infligge $s1 danni Arcani al bersaglio attuale." },
    [1280481] = { en = "Immobilizes a tool-stealing fox for $d.", description = "Immobilizza una volpe che ruba attrezzi per $d." },
    [1280530] = { en = "Calls upon the fury of Elune, marking two targets. After 5s each target detonates, dealing damage that is split among nearby allies.", description = "Invoca la furia di Elune, marchiando due bersagli. Dopo 5s ogni bersaglio esplode, infliggendo danni suddivisi tra gli alleati vicini." },
    [1280634] = { en = "Regenerates all nearby group members for $?$p456322[${$m1*2}][$s1] every $t1 seconds for $d.  Druid must channel to maintain the spell.", description = "Rigenera tutti i membri del gruppo vicini di $?$p456322[${$m1*2}][$s1] ogni $t1 secondi per $d. Il Druido deve incanalare l'incantesimo per mantenerlo." },
    [1280662] = { en = "Great sustenance fills the caster, increasing Physical damage dealt by $s1% and size by $s2%.", description = "Una grande energia pervade l'incantatore, aumentando i danni Fisici inflitti del $s1% e le dimensioni del $s2%." },
    [1280669] = { en = "Causes $s1 Fire damage to the target.", description = "Infligge $s1 danni da Fuoco al bersaglio." },
    [1280857] = { en = "Earned the respect of the Bolder'ok.", description = "Si è guadagnato il rispetto dei Bolder'ok." },
    [1281530] = { en = "Allows you to rent a mount for 2 minutes.", description = "Ti permette di noleggiare una cavalcatura per 2 minuti." },
    [1281641] = { en = "Right Click to summon and dismiss your musical froggy friend.", description = "Clic destro per evocare e congedare il tuo amico musicale ranocchio." },
    [1281765] = { en = "Places a magical seed that blooms after 5 sec. Treants are created every $1281782t1 sec.", description = "Pone un seme magico che sboccia dopo 5 sec. I Treant vengono creati ogni $1281782t1 sec." },
    [1281782] = { en = "Periodically summons Treants who attack nearby enemies.", description = "Evoca periodicamente dei Treant che attaccano i nemici vicini." },
    [1281887] = { en = "Recently Entangled.", description = "Intrappolato di recente." },
    [1282189] = { en = "Take a tuft of fur from Renalard's tail.", description = "Prendi un ciuffo di pelo dalla coda di Renalard." },
    [1282429] = { en = "Take a swatch of velvet from Kala'th's horns.", description = "Prendi un campione di velluto dalle corna di Kala'th." },
    [1282430] = { en = "Take a whisker from Shalla'kal.", description = "Prendi un baffo da Shalla'kal." },
    [1282482] = { en = "Sear certain enchanted targets with blazing light causing it to take additional damage from holy attacks and spells", description = "Brucia alcuni bersagli incantati con una luce ardente, facendogli subire danni aggiuntivi dagli attacchi e dagli incantesimi sacri" },
    [1282503] = { en = "Sear the target with a vortex of blazing wind, dealing $s1 Holystorm damage. Deals $s2 times as much damage to Wolves and Worgen.\r\n", description = "Colpisci il bersaglio con un vortice di vento ardente, infliggendo $s1 danni da tempesta sacra. Infligge danni moltiplicati per $s2 a Lupi e Worgen.\r\n" },
    [1282576] = { en = "Plant an explosive charge.", description = "Piazza una carica esplosiva." },
    [1282951] = { en = "Plant the makeshift banner to lure out the alliance scoutmaster.", description = "Piazza lo stendardo improvvisato per attirare il comandante degli esploratori dell'Alleanza." },
    [1283133] = { en = "Captures a subdued Twilight's Thrall. Only works on weakened enemies.", description = "Cattura un Servo del Crepuscolo soggiogato. Funziona solo sui nemici indeboliti." },
    [1283137] = { en = "Place bait to attract the sea monster.", description = "Piazza un'esca per attirare il mostro marino." },
    [1283400] = { en = "Craft a Journeyman Campfire.", description = "Crea un falò da garzone." },
    [1283620] = { en = "Create an Area Trigger with a Projected Texture at the targeted location. Lasts forever or until you leave the world, whichever is sooner.", description = "Crea un'area di attivazione con una texture proiettata nella posizione bersaglio. Dura per sempre o finché non lasci il mondo, a seconda di quale evento si verifichi prima." },
    [1283919] = { en = "A 'convincing' disguise Jereman put together so you will be able to infiltrate the warlock camp in the Tainted Foothills. Suspicious activity will break the disguise.", description = "Un travestimento «convincente» preparato da Jereman, che ti permetterà di infiltrarti nell'accampamento degli stregoni nelle Colline contaminate. Attività sospette interromperanno il travestimento." },
    [1284017] = { en = "Shows the location of all nearby beasts on the minimap. Only one form of tracking can be active at a time.", description = "Mostra la posizione di tutte le bestie vicine sulla minimappa. Può essere attiva una sola forma di tracciamento alla volta." },
    [1284560] = { en = "You are holding the Darkspear Flag.\r\nTake this flag to any controlled point to gain Victory Points.\r\n", description = "Stai trasportando la Bandiera degli Zannatorta.\r\nPorta questa bandiera a un qualsiasi punto controllato per ottenere Punti Vittoria.\r\n" },
    [1284701] = { en = "Use the Concoction of Cleansing on animals that have been experimented on with fel ash.", description = "Usa la Pozione detergente sugli animali sottoposti a esperimenti con la cenere vile." },
    [1284734] = { en = "Increases running and swimming speed by $s1%.", description = "Aumenta la velocità di corsa e di nuoto del $s1%." },
    [1284783] = { en = "Increase your reputation permanently with furbolg of Barkskin Burrow.", description = "Aumenta permanentemente la tua reputazione presso i furbolg della Tana Cortecce." },
    [1285372] = { en = "Allows the rogue to vanish from sight, entering an improved stealth mode for $11329d.  Also breaks movement impairing effects. More effective than Vanish (Rank 2).", description = "Permette al ladro di svanire dalla vista, entrando in una modalità di furtività migliorata per $11329d. Rimuove anche gli effetti che limitano il movimento. Più efficace di Svanimento (Grado 2)." },
    [1285835] = { en = "Channeling a crystal.", description = "Incanalamento di un cristallo." },
    [1285853] = { en = "Allows the player to ride a galestrider.", description = "Consente al giocatore di cavalcare un galestrider." },
    [1285903] = { en = "You are being hunted... good luck.", description = "Ti stanno dando la caccia... buona fortuna." },
    [1286024] = { en = "Summons and dismisses a rideable Empyrean Galestrider.", description = "Evoca e congeda un Empyrean Galestrider cavalcabile." },
    [1286025] = { en = "Summons and dismisses a rideable Regal Galestrider.", description = "Evoca e congeda un Regal Galestrider cavalcabile." },
    [1286026] = { en = "Summons and dismisses a rideable Stormy Galestrider.", description = "Evoca e congeda uno Stormy Galestrider cavalcabile." },
    [1286050] = { en = "Attempts to freeze the Blackthorne Pact in place, locking them in a block of ice and making them weak to Fire effects.", description = "Tenta di congelare sul posto il Patto di Blackthorne, intrappolandolo in un blocco di ghiaccio e rendendolo vulnerabile agli effetti di Fuoco." },
    [1286114] = { en = "Anara calls down stars at random player's locations every $t1 sec for $d. Each star inflicts $1294728s1 Arcane damage to all players within $1294728A1 yards of the impact.", description = "Anara fa cadere stelle in posizioni casuali dei giocatori ogni $t1 sec per $d. Ogni stella infligge $1294728s1 danni Arcani a tutti i giocatori entro $1294728A1 metri dall'impatto." },
    [1286800] = { en = "Deploy a banner representing your chosen faction in the Desolace centaur war for $d.", description = "Piazza per $d uno stendardo che rappresenta la fazione scelta nella guerra dei centauri di Desolace." },
    [1286814] = { en = "Transform into a centaur for $d or until you enter combat.\r\n\r\nWhile in Desolace, your movement speed is also increased by $s2% and this transformation persists through combat.", description = "Ti trasformi in un centauro per $d o finché non entri in combattimento.\r\n\r\nMentre ti trovi a Desolace, la tua velocità di movimento aumenta anche del $s2% e la trasformazione persiste durante il combattimento." },
    [1286850] = { en = "Bitten by Darkspear Shark! Taking damage equal to $s1% of your health every $t1 sec.\r\n", description = "Morso da uno squalo dei Lanciascura! Subisci danni pari al $s1% della tua salute ogni $t1 sec.\r\n" },
    [1287321] = { en = "Places a candle at a nearby grave.", description = "Piazza una candela presso una tomba vicina." },
    [1287327] = { en = "Place the last remains of the stag as an offering to return to nature.", description = "Offri gli ultimi resti del cervo per restituirli alla natura." },
    [1287557] = { en = "Absorb Twilight magic from Empowered Brutes, Twilight Ritualists, or Twilight Ritual Circles.", description = "Assorbi magia del Crepuscolo dai Bruti potenziati, dai Ritualisti del Crepuscolo o dai Cerchi rituali del Crepuscolo." },
    [1287571] = { en = "Increases all attributes by $s1 for $d. Effect and duration are doubled in Forest and Grassland areas.", description = "Aumenta tutti gli attributi di $s1 per $d. L'effetto e la durata raddoppiano nelle aree di foresta e prateria." },
    [1287664] = { en = "Gharalis' body decays and crumbles, increasing damage dealt by $S2% and damage taken by $S1%. ", description = "Il corpo di Gharalis marcisce e si sbriciola, aumentando i danni inflitti del $S2% e i danni subiti del $S1%. " },
    [1287735] = { en = "Stuns all players for %d. ", description = "Stordisce tutti i giocatori per %d. " },
    [1287773] = { en = "The power of Elune blesses the waters, increasing swim speed by $S1% per application.", description = "Il potere di Elune benedice le acque, aumentando la velocità di nuoto del $S1% per applicazione." },
    [1287808] = { en = "Reduces your magic damage taken from Dragon Breath spells by $s2% for $d.", description = "Riduce del $s2% per $d i danni magici subiti dagli incantesimi Soffio del Drago." },
    [1287839] = { en = "Melee and ranged attacks against Orcs and Ogres deal $s1% additional damage as Physical damage.", description = "Gli attacchi in mischia e a distanza contro Orchi e Ogre infliggono $s1% di danni Fisici aggiuntivi." },
    [1287840] = { en = "Increases your Spell Hit chance by $s1% for $d.", description = "Aumenta la probabilità di colpire con gli incantesimi del $s1% per $d." },
    [1287842] = { en = "Increases maximum health by $s1 for $d. This effect is doubled in Strongholds and Cities.", description = "Aumenta la salute massima di $s1 per $d. Questo effetto raddoppia nelle roccaforti e nelle città." },
    [1287963] = { en = "Summon a ring of light on a specific location that lasts for $d. Reveals ghosts of the past.", description = "Evoca un cerchio di luce in un luogo specifico per $d. Rivela i fantasmi del passato." },
    [1287976] = { en = "Fires a poisoned arrow at a target inflicting $s1 Nature and $s2 Nature damage every $t2 sec for $d.", description = "Scaglia una freccia avvelenata contro un bersaglio, infliggendo $s1 danni Natura e $s2 danni Natura ogni $t2 sec per $d." },
    [1288020] = { en = "Increases your spell damage and healing by up to $s1 for $d.", description = "Aumenta i danni degli incantesimi e le cure fino a $s1 per $d." },
    [1288021] = { en = "Increases your healing by up to $s1 for $d.", description = "Aumenta le cure fino a $s1 per $d." },
    [1288024] = { en = "Increases your ranged Attack Power by $s1 for $d.", description = "Aumenta la potenza d'attacco a distanza di $s1 per $d." },
    [1288298] = { en = "Add this profession's sign to your $?pc923[Orcish Tradeskill Sign][Dwarven Tradeskill Sign] toy for all characters on your account.\r\n\r\nCharacters that wish to display this sign must have that profession.", description = "Aggiungi l'insegna di questa professione al tuo giocattolo Insegna delle professioni $?pc923[orchesca][nanica] per tutti i personaggi del tuo account.\r\n\r\nI personaggi che desiderano esporre questa insegna devono avere quella professione." },
    [1288322] = { en = "Sign, initial, and date a long list of pages that are definitely not worth your time to read.\r\n\r\nThey're from a trustworthy source, so it's probably fine.", description = "Firma, sigla e data un lungo elenco di pagine che sicuramente non vale la pena leggere.\r\n\r\nProvengono da una fonte affidabile, quindi probabilmente è tutto a posto." },
    [1288388] = { en = "Calls forth three powerful stars to impact Anara's location inflicting $123456s1 Arcane damage to all players within $123456a1yards and knocking them back.", description = "Evoca tre potenti stelle che si abbattono sulla posizione di Anara, infliggendo $123456s1 danni Arcani a tutti i giocatori entro $123456a1metri e respingendoli." },
    [1288479] = { en = "The Huntress is empowered by the might of Elune, granting nearby allies increased Attack speed and Damage.", description = "La Cacciatrice è potenziata dalla forza di Elune e conferisce agli alleati vicini maggiore velocità d'attacco e danni." },
    [1288524] = { en = "Victims caught in the path of the glaive suffer Physical damage.\r\n", description = "Le vittime investite dal percorso della lama da lancio subiscono danni Fisici.\r\n" },
    [1288558] = { en = "Afflicts the target with a deadly curse that takes 6s to take effect. Upon expiration it deals $1290040s1 Shadow damage and reduces their damage dealt by $1290040s2%.", description = "Colpisce il bersaglio con una maledizione mortale che ha effetto dopo 6s. Alla scadenza infligge $1290040s1 danni d'Ombra e riduce i danni inflitti del bersaglio del $1290040s2%." },
    [1288559] = { en = "Inflicts the target with a poison that takes root after 10s. When Bloom expires it roots the target in place, dealing intense Nature damage over $d.", description = "Avvelena il bersaglio con una tossina che attecchisce dopo 10s. Alla scadenza di Fioritura, immobilizza il bersaglio e infligge intensi danni Natura per $d." },
    [1288560] = { en = "Slows the target, reducing their movement speed by $s1% and their Mana, Rage, and Energy generation.", description = "Rallenta il bersaglio, riducendone la velocità di movimento del $s1% e la generazione di Mana, Rabbia ed Energia." },
    [1288561] = { en = "Reduces an enemy's armor and resistances by $s1 for $d. While affected, the target cannot use stealth or invisibility.", description = "Riduce di $s1 l'armatura e le resistenze di un nemico per $d. Finché è sotto effetto, il bersaglio non può usare furtività o invisibilità." },
    [1288850] = { en = "Fires freezing arrow traps at multiple targets. After 3s these traps arm and freeze any target struck by them, stunning them for $12945353d and inflicting $1294353s1 Frost damage. A large patch of ice forms at their location, slowing enemy movement speed by $1294444s2% and inflicting $1294444s1 Frost damage every $1294444t1 sec.", description = "Scaglia trappole a freccia congelante contro più bersagli. Dopo 3s le trappole si attivano e congelano ogni bersaglio colpito, stordendolo per $12945353d e infliggendo $1294353s1 danni da Gelo. Nel punto colpito si forma un'ampia distesa di ghiaccio che rallenta la velocità di movimento dei nemici del $1294444s2% e infligge $1294444s1 danni da Gelo ogni $1294444t1 sec." },
    [1288908] = { en = "Hacks at the current target reducing their armor by $s1 and dealing $s2 Physical damage.  Lasts $d.", description = "Fende il bersaglio attuale, riducendone l'armatura di $s1 e infliggendo $s2 danni Fisici.  Dura $d." },
    [1288961] = { en = "Unleashes a barrage of bolts at a targets location inflicting Physical damage to players in a cone in front of the caster every sec for$d.", description = "Scatena una raffica di dardi sulla posizione di un bersaglio, infliggendo danni Fisici ai giocatori in un cono davanti all'incantatore ogni sec per $d." },
    [1289126] = { en = "Reduces healing received by $s1%.\r\n", description = "Riduce le cure ricevute del $s1%.\r\n" },
    [1289128] = { en = "Reduces the damage it takes by $s1% for $d.", description = "Riduce i danni subiti del $s1% per $d." },
}
for id, record in pairs(records) do
    local current = ns.data.spellDescriptionOverrides[id]
    if current == nil then
        ns.data.spellDescriptionOverrides[id] = record
    end
end
